      "module":"fieldservice","kind":"action_authorization","key":"fieldservice_actions","requirement_keys":["customer_asset_service","work_order_lifecycle","transactional_repair_completion","warranty_waiver","overdue_reminders","reporting_and_export"],"depends_on":["fieldservice/object_relation/fieldservice_objects","fieldservice/actor_role/fieldservice_access","fieldservice/resource/notification_contracts"],
      "payload":{"emits":[
        {"collection":"actions","key":"service_request.submit_service_request","value":{
          "name":"Submit service request","object_key":"service_request","kind":"object_operation","audit_event":"service_request.submitted",
          "payload_fields":[
            {"key":"request_id","name":"Request ID","type":"text","required":true},
            {"key":"device_id","name":"Device","type":"relation","target_object_key":"device","required":true},
            {"key":"fault_description","name":"Fault description","type":"long_text","required":true},
            {"key":"preferred_visit_at","name":"Preferred visit time","type":"datetime","required":true},
            {"key":"submitted_at","name":"Submitted at","type":"datetime","required":true}
          ],
          "idempotency_keys":["request_id"],"authorization":{"allowed_roles":["customer"]},
          "handler":{"data_access":[{"object_key":"customer_profile","operations":["list"]},{"object_key":"device","operations":["get"]},{"object_key":"service_request","operations":["create"]}],"output":[{"key":"service_request_id","name":"Service request","type":"relation","target_object_key":"service_request","required":true},{"key":"status","name":"Status","type":"select","required":true,"options":["submitted"]}]}
        }},
        {"collection":"actions","key":"service_request.dispatch_service_request","value":{
          "name":"Dispatch service request","object_key":"service_request","kind":"record_operation","audit_event":"service_request.dispatched",
          "payload_fields":[{"key":"request_id","name":"Request ID","type":"text","required":true},{"key":"assigned_user_id","name":"Assigned technician","type":"user","required":true},{"key":"organization_unit_id","name":"Station ID","type":"text","required":true},{"key":"dispatched_at","name":"Dispatched at","type":"datetime","required":true}],
          "idempotency_keys":["request_id"],"authorization":{"allowed_roles":["ops_manager"]},
          "handler":{"notification_event_types":["service_request.assigned"],"data_access":[{"object_key":"service_request","operations":["get_for_update","conditional_update"]}],"output":[{"key":"service_request_id","name":"Service request","type":"relation","target_object_key":"service_request","required":true},{"key":"status","name":"Status","type":"select","required":true,"options":["dispatched"]}]}
        }},
        {"collection":"actions","key":"service_request.unassign_service_request","value":{
          "name":"Unassign service request","object_key":"service_request","kind":"record_operation","audit_event":"service_request.unassigned",
          "payload_fields":[{"key":"request_id","name":"Request ID","type":"text","required":true}],"idempotency_keys":["request_id"],"authorization":{"allowed_roles":["ops_manager"]},
          "handler":{"data_access":[{"object_key":"service_request","operations":["get_for_update","conditional_update"]}],"output":[{"key":"service_request_id","name":"Service request","type":"relation","target_object_key":"service_request","required":true},{"key":"status","name":"Status","type":"select","required":true,"options":["submitted"]}]}
        }},
        {"collection":"actions","key":"service_request.start_assigned_repair","value":{
          "name":"Start assigned repair","object_key":"service_request","kind":"record_operation","audit_event":"service_request.repair_started",
          "payload_fields":[{"key":"request_id","name":"Request ID","type":"text","required":true},{"key":"started_at","name":"Started at","type":"datetime","required":true}],"idempotency_keys":["request_id"],"authorization":{"allowed_roles":["technician"]},
          "handler":{"data_access":[{"object_key":"service_request","operations":["get_for_update","conditional_update"]}],"output":[{"key":"service_request_id","name":"Service request","type":"relation","target_object_key":"service_request","required":true},{"key":"status","name":"Status","type":"select","required":true,"options":["in_repair"]}]}
        }},
        {"collection":"actions","key":"service_request.complete_repair","value":{
          "name":"Complete repair","object_key":"service_request","kind":"record_operation","audit_event":"service_request.completed",
          "payload_fields":[
            {"key":"request_id","name":"Request ID","type":"text","required":true},
            {"key":"quote_amount","name":"Quoted fee","type":"currency","source_object_key":"service_request","source_field_key":"quote_amount","required":true},
            {"key":"usage_lines_json","name":"Usage lines JSON","type":"long_text","required":true},
            {"key":"completed_at","name":"Completed at","type":"datetime","required":true}
          ],
          "idempotency_keys":["request_id"],"authorization":{"allowed_roles":["technician"]},
          "handler":{"data_access":[{"object_key":"service_request","operations":["get_for_update","conditional_update"]},{"object_key":"spare_part","operations":["get_for_update","conditional_update"]},{"object_key":"part_usage","operations":["create"]},{"object_key":"fee_ledger","operations":["create"]}],"output":[{"key":"service_request_id","name":"Service request","type":"relation","target_object_key":"service_request","required":true},{"key":"usage_count","name":"Usage count","type":"integer","required":true},{"key":"fee_ledger_id","name":"Fee ledger","type":"relation","target_object_key":"fee_ledger","required":true}]}
        }},
        {"collection":"actions","key":"service_request.request_warranty_waiver","value":{
          "name":"Request warranty waiver","object_key":"service_request","kind":"record_operation","audit_event":"warranty_waiver.requested",
          "payload_fields":[
            {"key":"request_id","name":"Request ID","type":"text","required":true},
            {"key":"requested_amount","name":"Requested waiver","type":"currency","source_object_key":"warranty_waiver","source_field_key":"requested_amount","required":true},
            {"key":"warranty_asserted","name":"Warranty eligibility asserted","type":"boolean","required":true},
            {"key":"requested_at","name":"Requested at","type":"datetime","required":true}
          ],
          "idempotency_keys":["request_id"],"preconditions":["status == completed"],"authorization":{"allowed_roles":["technician"]},
          "handler":{"notification_event_types":["warranty_waiver.requested","warranty_waiver.resolved"],"data_access":[{"object_key":"service_request","operations":["get"]},{"object_key":"warranty_waiver","operations":["exists","create"]},{"object_key":"fee_ledger","operations":["create"]}],"output":[{"key":"warranty_waiver_id","name":"Warranty waiver","type":"relation","target_object_key":"warranty_waiver","required":true},{"key":"status","name":"Status","type":"select","required":true,"options":["pending","applied"]}]}
        }},
        {"collection":"actions","key":"warranty_waiver.approve_warranty_waiver","value":{
          "name":"Approve warranty waiver","object_key":"warranty_waiver","kind":"record_operation","audit_event":"warranty_waiver.approved",
          "payload_fields":[{"key":"decided_at","name":"Decided at","type":"datetime","required":true}],
          "idempotency_keys":["decided_at"],"preconditions":["status == pending"],"authorization":{"allowed_roles":["ops_manager"]},
          "handler":{"notification_event_types":["warranty_waiver.resolved"],"data_access":[{"object_key":"warranty_waiver","operations":["get_for_update","conditional_update"]},{"object_key":"fee_ledger","operations":["create"]}],"output":[{"key":"warranty_waiver_id","name":"Warranty waiver","type":"relation","target_object_key":"warranty_waiver","required":true},{"key":"status","name":"Status","type":"select","required":true,"options":["applied"]}]}
        }},
        {"collection":"actions","key":"warranty_waiver.reject_warranty_waiver","value":{
          "name":"Reject warranty waiver","object_key":"warranty_waiver","kind":"record_operation","audit_event":"warranty_waiver.rejected",
          "payload_fields":[{"key":"rejection_reason","name":"Rejection reason","type":"long_text","required":true},{"key":"decided_at","name":"Decided at","type":"datetime","required":true}],
          "idempotency_keys":["decided_at"],"preconditions":["status == pending"],"authorization":{"allowed_roles":["ops_manager"]},
          "handler":{"notification_event_types":["warranty_waiver.resolved"],"data_access":[{"object_key":"warranty_waiver","operations":["get_for_update","conditional_update"]}],"output":[{"key":"warranty_waiver_id","name":"Warranty waiver","type":"relation","target_object_key":"warranty_waiver","required":true},{"key":"status","name":"Status","type":"select","required":true,"options":["rejected"]}]}
        }},
        {"collection":"actions","key":"service_request.send_overdue_reminder","value":{
          "name":"Send overdue reminder","object_key":"service_request","kind":"record_operation","audit_event":"service_request.overdue_reminder_sent",
          "payload_fields":[{"key":"scheduled_at","name":"Scheduled at","type":"datetime","required":true}],"idempotency_keys":["scheduled_at"],"preconditions":["status == dispatched"],"authorization":{"allowed_roles":["scheduler_service"]},
          "handler":{"notification_event_types":["service_request.overdue"],"data_access":[{"object_key":"service_request","operations":["get"]},{"object_key":"overdue_reminder","operations":["exists","create"]}],"output":[{"key":"created","name":"Reminder created","type":"boolean","required":true},{"key":"overdue_reminder_id","name":"Reminder ID","type":"relation","target_object_key":"overdue_reminder","required":false}]}
        }},
        {"collection":"actions","key":"report_export_audit.request_work_order_export","value":{
          "name":"Request work-order export","object_key":"report_export_audit","kind":"object_create","audit_event":"report_export.requested","permission":"report_export_audit.create",
          "payload_fields":[{"key":"report_key","name":"Report key","type":"text","required":true},{"key":"status","name":"Status","type":"select","required":true,"options":["requested"]},{"key":"purpose","name":"Purpose","type":"long_text","required":true},{"key":"requested_at","name":"Requested at","type":"datetime","required":true}],
          "idempotency_keys":["report_key","requested_at"]
        }}
      ]}
    }
  ]
