func knownPrincipal() capabilities.Principal {
	return capabilities.Principal{Known: true, UserID: "test-user"}
}

func assertBusinessErrorCode(t *testing.T, err error, expected string) {
	t.Helper()
	var businessError *capabilities.BusinessError
	if !errors.As(err, &businessError) {
		t.Fatalf("expected BusinessError %q, got %T %v", expected, err, err)
	}
	if businessError.Code != expected {
		t.Fatalf("expected BusinessError %q, got %q", expected, businessError.Code)
	}
}
